import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.DaGSOal_.js";const h=JSON.parse('{"title":"Compatibility","description":"Check Unreal Engine versions and supported plugin environments.","frontmatter":{"title":"Compatibility","description":"Check Unreal Engine versions and supported plugin environments."},"headers":[],"relativePath":"compatibility.md","filePath":"compatibility.md","lastUpdated":1794040252000}'),r={name:"compatibility.md"};function o(l,e,s,d,p,u){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h1><p>Plugin compatibility depends on the product version and the Unreal Engine release. The <a href="https://www.fab.com/de/sellers/Deblx" target="_blank" rel="noreferrer">Fab Marketplace</a> listing is the source for currently supported versions.</p><h2 id="unreal-engine-versions" tabindex="-1">Unreal Engine Versions <a class="header-anchor" href="#unreal-engine-versions" aria-label="Permalink to &quot;Unreal Engine Versions&quot;">​</a></h2><p>All plugins support <strong>Unreal Engine 5.1+</strong>. Choose the exact engine version that is available for the plugin in your Fab Library.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Some older installation guides mention engine versions available at the time they were written. Confirm availability in Fab before installing a plugin into a new Unreal Engine version.</p></div><table tabindex="0"><thead><tr><th>Plugin</th><th>Guide</th></tr></thead><tbody><tr><td>Loading Screen Pro</td><td><a href="/loading-screen-pro/installation">Installation</a></td></tr><tr><td>Quick Notes / ToDo</td><td><a href="/quick-notes/installation">Installation</a></td></tr><tr><td>Duplicate Asset Detector Pro</td><td><a href="/duplicate-asset-detector/installation">Installation</a></td></tr><tr><td>Asset Size Analyzer</td><td><a href="/asset-size-analyzer/installation">Installation</a></td></tr></tbody></table><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li>Locate your plugin in the Fab Library in the Epic Games Launcher.</li><li>Choose <strong>Install to Engine</strong> and select an available engine version.</li><li>Open your Unreal Engine project, then enable the plugin under <strong>Edit → Plugins</strong>.</li><li>Restart the editor if requested.</li></ol><h2 id="plugin-types" tabindex="-1">Plugin Types <a class="header-anchor" href="#plugin-types" aria-label="Permalink to &quot;Plugin Types&quot;">​</a></h2><p><strong>Editor-only:</strong> Quick Notes / ToDo, Duplicate Asset Detector Pro and Asset Size Analyzer focus on workflows inside the Unreal Editor.</p><p><strong>Runtime and editor:</strong> Loading Screen Pro provides runtime loading visuals along with editor configuration and preview features.</p><h2 id="updating-plugins" tabindex="-1">Updating Plugins <a class="header-anchor" href="#updating-plugins" aria-label="Permalink to &quot;Updating Plugins&quot;">​</a></h2><p>Review the <a href="https://changelog.deblx.com" target="_blank" rel="noreferrer">Deblx Changelog</a> for release announcements. If a documented step differs from what you see, include your plugin and engine versions when contacting <a href="/support">Support</a>.</p>',13)])])}const g=t(r,[["render",o]]);export{h as __pageData,g as default};
